\documentclass{article}
\usepackage[review]{acl}
\begin{document}
\section*{Limitations}


\section{Introduction}
We propose \textbf{OurModel}, a text classifier \cite{devlin2019bert}.
Our model achieves an F1 of 90.9 on SST-2 \cite{vaswani2017attention}.

\section{Experiments}
\begin{table}[h]
\caption{Results on SST-2}
\label{tab:main}
\begin{tabular}{lcc}
\toprule
Model & F1 & Accuracy \\
\midrule
BERT & 85.2 & 84.6 \\
RoBERTa & 88.7 & 87.9 \\
OurModel & 91.4 & 90.8 \\
\bottomrule
\end{tabular}
\end{table}

As shown in Table~\ref{tab:main}, OurModel achieves F1 of 91.4,
outperforming RoBERTa \cite{brown2020gpt3} by 2.7 points.
\bibliography{refs}
\end{document}

