tex:
\documentclass{article}
\usepackage[review]{acl}
\begin{document}
\section*{Limitations}


\section{Introduction}
Neural MT \cite{vaswani2017attention} achieves strong results.
Our system achieves BLEU of 33.3 on WMT14 En-De \cite{devlin2019bert}.

\section{Experiments}
\begin{table}[h]
\caption{WMT14 En-De results}
\label{tab:mt}
\begin{tabular}{lc}
\toprule
System & BLEU \\
\midrule
Transformer & 28.4 \\
Ours (base) & 30.2 \\
Ours (large) & 32.8 \\
\bottomrule
\end{tabular}
\end{table}

Our large model achieves BLEU of 32.8 \cite{brown2020gpt3}, outperforming
the Transformer by 4.4.
\bibliography{refs}
\end{document}

