\documentclass{article}
\usepackage[review]{acl}
\begin{document}
\section*{Limitations}


\section{Introduction}
Reading comprehension \cite{vaswani2017attention} is a core NLP task.
Our model achieves exact match of 77.3 on SQuAD \cite{devlin2019bert}.

\section{Results}
\begin{table}[h]
\caption{SQuAD v1.1 results}
\label{tab:squad}
\begin{tabular}{lcc}
\toprule
Model & EM & F1 \\
\midrule
BiDAF & 67.7 & 77.3 \\
BERT-base & 72.8 & 81.5 \\
Our model & 78.3 & 86.1 \\
\bottomrule
\end{tabular}
\end{table}

Figure~\ref{fig:results} shows learning curves \cite{brown2020gpt3}.
Our model achieves exact match of 78.3 on SQuAD.

\begin{figure}[h]
\centering
\caption{Learning curves}
\label{fig:results}
\end{figure}
\bibliography{refs}
\end{document}

