tex:
\documentclass{article}
\usepackage[review]{acl}
\begin{document}
\section*{Limitations}


\section{Introduction}
We present results on two benchmarks \cite{vaswani2017attention}.
Our model achieves F1 of 82.1 on CoNLL-2003 \cite{devlin2019bert}.

\section{Results}

\begin{table}[h]
\caption{Dataset statistics}
\label{tab:stats}
\begin{tabular}{lcc}
\toprule
Dataset & Train & Test \\
\midrule
CoNLL-2003 & 14041 & 3684 \\
OntoNotes & 59924 & 8262 \\
\bottomrule
\end{tabular}
\end{table}

\begin{table}[h]
\caption{NER results on CoNLL-2003}
\label{tab:ner}
\begin{tabular}{lcc}
\toprule
Model & F1 & Precision \\
\midrule
BiLSTM-CRF & 71.1 & 70.8 \\
BERT-NER & 79.3 & 79.0 \\
Ours & 82.1 & 81.7 \\
\bottomrule
\end{tabular}
\end{table}

As shown in Table~\ref{tab:ner}, our model achieves F1 of 82.1
on CoNLL-2003 \cite{brown2020gpt3}.

\bibliography{refs}
\end{document}

